const recipes = $('Get Top Recipes (last 24h)').first().json.recipes || [];
const users = $input.first().json.users || [];
const appUrl = 'http://localhost:5173';

if (recipes.length === 0) return [{ json: { skip: true } }];

const recipeCards = recipes.map(r => `
  <div style="border:1px solid #e5e7eb;border-radius:12px;padding:16px;margin-bottom:12px;background:white">
    <h3 style="color:#15803d;margin:0 0 6px">${r.title}</h3>
    <p style="color:#6b7280;font-size:14px;margin:0 0 8px">${r.description || ''}</p>
    <p style="color:#9ca3af;font-size:12px">by @${r.username} · 🔖 ${r.save_count} saves · ❤️ ${r.like_count} likes</p>
    <a href="${appUrl}/recipe/${r.id}" style="color:#16a34a;font-size:14px;font-weight:600">View Recipe →</a>
  </div>
`).join('');

const html = `
  <div style="font-family:Inter,sans-serif;max-width:600px;margin:0 auto;padding:32px;background:#f0fdf4;border-radius:16px">
    <h1 style="color:#16a34a;font-size:24px">🥗 Today's Top Nourishly Recipes</h1>
    <p style="color:#374151">Here are the most-loved recipes from the past 24 hours:</p>
    ${recipeCards}
    <a href="${appUrl}" style="display:inline-block;background:#16a34a;color:white;padding:12px 24px;border-radius:12px;text-decoration:none;font-weight:600;margin-top:8px">See All Recipes →</a>
    <p style="color:#9ca3af;font-size:11px;margin-top:24px">You're receiving this because you're a Nourishly member. Nourishly — Cook Better. Live Better.</p>
  </div>
`;

return users.map(u => ({ json: { to: u.email, username: u.username, subject: "🥗 Today's top Nourishly recipes for you", html } }));
